/**
 * Show business, 1960: the Jersey Shore / Philadelphia / New York / Las Vegas /
 * Hollywood circuit. Doo-wop groups and rock-and-roll kids on Pacific Avenue,
 * lounge singers and comics in the supper clubs, a Philadelphia TV dance-show
 * host in the middle of the payola scandal (1959-60 Congressional hearings),
 * DJs, actresses and actors, producers, directors, agents and columnists.
 *
 * Every person here is fictional. Nobody is a real performer, and nothing is
 * explicit. The stag-film racket exists only as an abstract business in the
 * engine; no performer in this file is tied to it.
 *
 * mobIntersect lists how each person can cross the player's path: bookings,
 * debts, payola, film investment, blackmail, protection, jukeboxes, liquor
 * licenses, skim, courier work, fronts, record pressing, contract buyouts,
 * or a marriage into a political family.
 */
import { P } from './build';
import type { Archetype } from './generators';
import type {
  Circuit, MobIntersect, Origin, RelKind, SecretKind, ShowbizCategory, TieKind, Trajectory, WorldPerson, WorldTrait, WorldVice,
} from './schema';

const BUSINESS_CATS: ShowbizCategory[] = ['producer', 'director', 'club-owner', 'agent', 'columnist', 'songwriter', 'record-man', 'promoter', 'photographer'];
const LABEL: Record<ShowbizCategory, string> = {
  'doo-wop': 'Vocal group singer', 'rock-and-roll': 'Rock and roll singer', 'lounge-singer': 'Lounge singer', jazz: 'Jazz musician', comic: 'Comedian',
  bandleader: 'Bandleader', dancer: 'Dancer', 'tv-host': 'Television host', dj: 'Disc jockey', actress: 'Actress', actor: 'Actor', producer: 'Producer',
  director: 'Director', 'club-owner': 'Nightclub owner', agent: 'Talent agent', columnist: 'Columnist', songwriter: 'Songwriter', 'record-man': 'Record man',
  promoter: 'Promoter', photographer: 'Photographer',
};

interface Ent {
  id: string; n: string; last?: string; nick?: string; f?: boolean; b: number; o: Origin; home: string;
  cat: ShowbizCategory; act?: string; cir: Circuit[]; tr: Trajectory; fame: number; peak: number; risk: number; mob: MobIntersect[]; fee?: number;
  a: Archetype; t: WorldTrait[]; v?: WorldVice[]; pub: string; hid: string; hook: string; w?: number;
  rel?: [RelKind, string, string?][]; s?: [SecretKind, 1 | 2 | 3, string, string?, boolean?, string[]?][];
  debt?: [string, 'money' | 'favor' | 'loyalty', number, string?][]; ties?: [TieKind, string, number, string?][];
}

function E(x: Ent): WorldPerson {
  const biz = BUSINESS_CATS.includes(x.cat);
  const rung = biz ? (x.fame < 35 ? 0 : x.fame < 75 ? 1 : 2) : (x.fame < 30 ? 0 : x.fame < 55 ? 1 : x.fame < 80 ? 2 : 3);
  return P({
    id: x.id, n: x.n, last: x.last, nick: x.nick, f: x.f, b: x.b, o: x.o, home: x.home, inst: 'showbiz',
    off: `${LABEL[x.cat]}${x.act ? `, ${x.act}` : ''}`, lad: [biz ? 'showbiz_business' : 'showbiz_performer', rung],
    a: x.a, t: x.t, v: x.v, pub: x.pub, hid: x.hid, hook: x.hook, rel: x.rel, s: x.s, debt: x.debt, ties: x.ties,
    w: x.w ?? Math.round((500 + x.fame * x.fame * 6) / 100) * 100,
    sh: { cat: x.cat, act: x.act, cir: x.cir, tr: x.tr, fame: x.fame, peak: x.peak, risk: x.risk, mob: x.mob, fee: x.fee },
  });
}

